search.script:
try {
  // Human-like search with anti-detection measures

  // Dismiss any notification banners that may overlay the search form
  await page.evaluate(function() {
    var banner = document.querySelector('[data-testid="bannerContainer"], .gnav-NotificationContainer, [class*="cookie"] button, [class*="banner"] button[aria-label*="lose"], button[aria-label="Close"]');
    if (banner) banner.click();
  });
  await page.randomDelay(300, 600);

  // Wait for keyword input
  await page.waitForSelector('#text-input-what', { timeout: 8000 });
  await page.randomDelay(500, 1000);

  // Fill keyword input with human-like typing
  if (params.keywords) {
    await page.humanType('#text-input-what', params.keywords);
  }

  await page.randomDelay(800, 1500);

  // Fill location input (humanType handles clearing automatically)
  if (params.location) {
    await page.humanType('#text-input-where', params.location);
    await page.randomDelay(500, 1000);
  }

  // Dismiss autocomplete dropdown by pressing Escape
  await page.keyboard.press('Escape');
  await page.randomDelay(300, 600);

  // Submit the search form
  await page.humanClick('button[type="submit"].yosegi-InlineWhatWhere-primaryButton');
  await page.waitForNavigation({ timeout: 15000 });
  await page.randomDelay(1500, 3000);

  // Check for Cloudflare / anti-bot after navigation
  await page.checkAntiBot({ maxWait: 45000 });

  // Apply job type filter via URL if specified
  if (params.jobType) {
    var jobTypeMap = {
      'fulltime': 'jt=fulltime',
      'parttime': 'jt=parttime',
      'contract': 'jt=contract',
      'temporary': 'jt=temporary',
      'internship': 'jt=internship'
    };
    var jtParam = jobTypeMap[params.jobType.toLowerCase().replace(/[-_ ]/g, '')] || '';
    if (jtParam) {
      var currentUrl = await page.url();
      var separator = currentUrl.includes('?') ? '&' : '?';
      await page.goto(currentUrl + separator + jtParam);
      await page.randomDelay(2000, 3000);
      await page.checkAntiBot({ maxWait: 30000 });
    }
  }

  // Apply salary filter via URL if specified
  if (params.minSalary) {
    var curUrl = await page.url();
    var sep = curUrl.includes('?') ? '&' : '?';
    await page.goto(curUrl + sep + 'salary=' + params.minSalary);
    await page.randomDelay(2000, 3000);
    await page.checkAntiBot({ maxWait: 30000 });
  }

  // Wait for job cards to load
  await page.waitForSelector('.jcs-JobTitle', { timeout: 10000 });
  await page.randomDelay(800, 1500);

  // Extract job listings (read-only DOM extraction is fine)
  var jobs = await page.evaluate(function() {
    var results = [];
    var cards = document.querySelectorAll('.job_seen_beacon, .cardOutline, [data-jk]');

    cards.forEach(function(card) {
      try {
        var titleEl = card.querySelector('.jcs-JobTitle');
        var title = titleEl ? titleEl.textContent.trim() : '';

        var url = '';
        if (titleEl) {
          var href = titleEl.getAttribute('href') || '';
          if (href.startsWith('http')) {
            url = href;
          } else if (href) {
            url = 'https://ca.indeed.com' + href;
          }
        }

        var companyEl = card.querySelector('[data-testid="company-name"], .companyName, .company_location .companyName a, span.css-1h7lukg, [class*="company"]');
        var company = companyEl ? companyEl.textContent.trim() : '';

        var locationEl = card.querySelector('[data-testid="text-location"], .companyLocation, [class*="location"]');
        var location = locationEl ? locationEl.textContent.trim() : '';

        var salaryEl = card.querySelector('.salary-snippet-container, [class*="salary"], .metadata.salary-snippet-container, [data-testid="attribute_snippet_testid"]');
        var salary = salaryEl ? salaryEl.textContent.trim() : '';

        var descEl = card.querySelector('.job-snippet, .underShelfFooter, [class*="snippet"], .heading6 ul');
        var description = descEl ? descEl.textContent.trim() : '';

        if (title) {
          results.push({ title: title, company: company, url: url, location: location, salary: salary, description: description });
        }
      } catch (e) {
        // Skip malformed cards
      }
    });

    return results;
  });

  return { success: true, jobs: jobs };
} catch (error) {
  return { success: false, error: error.message || String(error) };
}
